From 03dff76571273c1efcfd66e9a79115ac0d8880db Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:07:32 +0100
Subject: [PATCH] xkb: report the default layout when none is configured

With no layout in kxkbrc, locale1 or XKB_DEFAULT_LAYOUT, libxkbcommon
uses its own default but the layout list stayed empty, so the layout had
no short name. Take the list from the names libxkbcommon resolves.

BUG: 522449
---
 CMakeLists.txt          |  5 +++++
 src/config-kwin.h.cmake |  1 +
 src/xkb.cpp             | 18 +++++++++++++++---
 3 files changed, 21 insertions(+), 3 deletions(-)

diff --git a/CMakeLists.txt b/CMakeLists.txt
index d55ae62a8b..6cde0590d4 100644
--- a/CMakeLists.txt
+++ b/CMakeLists.txt
@@ -245,6 +245,11 @@ if (XKB_VERSION VERSION_GREATER_EQUAL 1.5.0)
 else()
     set(HAVE_XKBCOMMON_NO_SECURE_GETENV 0)
 endif()
+if (XKB_VERSION VERSION_GREATER_EQUAL 1.9.0)
+    set(HAVE_XKBCOMMON_RESOLVE_RULE_NAMES 1)
+else()
+    set(HAVE_XKBCOMMON_RESOLVE_RULE_NAMES 0)
+endif()

 find_package(Canberra REQUIRED)

diff --git a/src/config-kwin.h.cmake b/src/config-kwin.h.cmake
index dc69b07e66..7882786e5d 100644
--- a/src/config-kwin.h.cmake
+++ b/src/config-kwin.h.cmake
@@ -28,6 +28,7 @@ constexpr QLatin1StringView LIBEXEC_DIR("${CMAKE_INSTALL_FULL_LIBEXECDIR}");
 #cmakedefine01 HAVE_MEMFD
 #cmakedefine01 HAVE_SCHED_RESET_ON_FORK
 #cmakedefine01 HAVE_XKBCOMMON_NO_SECURE_GETENV
+#cmakedefine01 HAVE_XKBCOMMON_RESOLVE_RULE_NAMES
 #cmakedefine01 HAVE_DL_LIBRARY
 #cmakedefine01 HAVE_LIBINPUT_PLUGINS
 #cmakedefine01 HAVE_SYSTEMD
diff --git a/src/xkb.cpp b/src/xkb.cpp
index f5c6225a83..3e8550e55a 100644
--- a/src/xkb.cpp
+++ b/src/xkb.cpp
@@ -575,6 +575,18 @@ void Xkb::applyEnvironmentRules(xkb_rule_names &ruleNames)
     }
 }

+static QStringList layoutList(xkb_context *context, const xkb_rule_names &ruleNames)
+{
+#if HAVE_XKBCOMMON_RESOLVE_RULE_NAMES
+    // with no layout given, libxkbcommon falls back to its own default one
+    xkb_rule_names resolved = {};
+    if (xkb_components_names_from_rules(context, &ruleNames, &resolved, nullptr)) {
+        return QString::fromLatin1(resolved.layout).split(QLatin1Char(','));
+    }
+#endif
+    return QString::fromLatin1(ruleNames.layout).split(QLatin1Char(','));
+}
+
 XkbKeymapPtr Xkb::loadKeymapFromConfig()
 {
     // load config
@@ -600,7 +612,7 @@ XkbKeymapPtr Xkb::loadKeymapFromConfig()

     applyEnvironmentRules(ruleNames);

-    m_layoutList = QString::fromLatin1(ruleNames.layout).split(QLatin1Char(','));
+    m_layoutList = layoutList(m_context, ruleNames);

     return XkbKeymapPtr(xkb_keymap_new_from_names(m_context, &ruleNames, XKB_KEYMAP_COMPILE_NO_FLAGS));
 }
@@ -609,7 +621,7 @@ XkbKeymapPtr Xkb::loadDefaultKeymap()
 {
     xkb_rule_names ruleNames = {};
     applyEnvironmentRules(ruleNames);
-    m_layoutList = QString::fromLatin1(ruleNames.layout).split(QLatin1Char(','));
+    m_layoutList = layoutList(m_context, ruleNames);
     return XkbKeymapPtr(xkb_keymap_new_from_names(m_context, &ruleNames, XKB_KEYMAP_COMPILE_NO_FLAGS));
 }

@@ -633,7 +645,7 @@ XkbKeymapPtr Xkb::loadKeymapFromLocale1()

     applyEnvironmentRules(ruleNames);

-    m_layoutList = QString::fromLatin1(ruleNames.layout).split(QLatin1Char(','));
+    m_layoutList = layoutList(m_context, ruleNames);

     return XkbKeymapPtr(xkb_keymap_new_from_names(m_context, &ruleNames, XKB_KEYMAP_COMPILE_NO_FLAGS));
 }
-- 
